#!/usr/bin/env python3
"""Modernized climate data analysis script for Python 3."""

import configparser
from pathlib import Path

import numpy as np
import pandas as pd


class ClimateAnalyzer:
    def __init__(self, config_path: str = "config.ini"):
        self.config = configparser.ConfigParser()
        self.config.read(config_path, encoding="utf-8")
        self.data_cache = {}

    def load_temperature_data(self, filepath: Path) -> pd.DataFrame:
        df = pd.read_csv(filepath, parse_dates=["date"], encoding="utf-8")
        return df

    def calculate_anomalies(self, temperature_series: pd.Series) -> np.ndarray:
        baseline = np.mean(temperature_series)
        return temperature_series.to_numpy() - baseline

    def run_analysis(self):
        data_path = Path(__file__).parent / "climate_analyzer" / "sample_data" / "climate_data.csv"
        df = self.load_temperature_data(data_path)

        for station_id, group in df.groupby("station_id"):
            mean_temp = group["temperature"].mean()
            print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    analyzer = ClimateAnalyzer(
        config_path=str(Path(__file__).parent / "climate_analyzer" / "config.ini")
    )
    analyzer.run_analysis()

